    def load_overdue_tab(self):
        # Xóa dữ liệu cũ nếu bảng đã có dữ liệu
        for item in self.tlate.get_children():
            self.tlate.delete(item)

        c = self.db.conn.cursor()
        c.execute("""
            SELECT b.id, r.name, r.phone, bo.title, b.due_date
            FROM borrowings b
            JOIN readers r ON r.id = b.reader_id
            JOIN books bo ON bo.id = b.book_id
            WHERE b.status = 'Borrowing'
            ORDER BY b.due_date
        """)

        today = datetime.now().date()

        for bid, reader, phone, book, due_text in c.fetchall():
            due_date = datetime.strptime(due_text, "%Y-%m-%d").date()
            late_days = (today - due_date).days

            # Chỉ hiển thị phiếu đang mượn đã quá hạn
            if late_days > 0:
                fine = late_days * FINE_PER_DAY
                self.tlate.insert(
                    "", "end",
                    values=("☐", bid, reader, phone, book,
                        self.fd(due_text), "{} ngày".format(late_days),
                        "{:,} VNĐ".format(fine))
                )

    def confirm_on_time_returns(self):
        c = self.db.conn.cursor()

        c.execute("""
            SELECT id, book_id, due_date, request_date
            FROM borrowings
            WHERE status = 'PendingReturn'
        """)
        rows = c.fetchall()

        today = datetime.now().date()
        valid_rows = []

        for bid, book_id, due, req in rows:
            if not due or not req:
                continue

            try:
                due_date = datetime.strptime(
                    due, "%Y-%m-%d"
                ).date()
                request_date = datetime.strptime(
                    req, "%Y-%m-%d"
                ).date()
            except (ValueError, TypeError):
                continue

            if request_date <= due_date:
                valid_rows.append(
                    (bid, book_id, request_date)
                )

        if not valid_rows:
            messagebox.showinfo(
                "Duyệt phiếu",
                "Không có phiếu chờ xác nhận nào trả đúng hạn."
            )
            return

        if not messagebox.askyesno(
            "Xác nhận",
            "Duyệt {} phiếu trả sách đúng hạn?".format(
                len(valid_rows)
            )
        ):
            return

        try:
            approved = 0

            for bid, book_id, request_date in valid_rows:
                c.execute("""
                    UPDATE borrowings
                    SET status = 'Returned',
                        return_date = ?,
                        fine = 0
                    WHERE id = ?
                      AND status = 'PendingReturn'
                """, (request_date.isoformat(), bid))

                if c.rowcount > 0:
                    c.execute("""
                        UPDATE books
                        SET available = available + 1
                        WHERE id = ?
                    """, (book_id,))
                    approved += 1

            self.db.conn.commit()

        except Exception as e:
            self.db.conn.rollback()
            messagebox.showerror(
                "Lỗi",
                "Không thể duyệt phiếu:\n{}".format(e)
            )
            return

        self.checked_rows["pending"].clear()
        self.pending_checked.clear()
        self.load_pending()
        self.load_returns()
        self.load_overdue_tab()

        messagebox.showinfo(
            "Thành công",
            "Đã duyệt {} phiếu trả sách đúng hạn.".format(
                approved
            )
        )

    def confirm_selected_returns(self):
        selected_rows = list(
            self.checked_rows.get("pending", set())
        )

        selected_ids = []

        for row_id in selected_rows:
            if not self.tpend.exists(row_id):
                continue

            values = self.tpend.item(row_id, "values")

            if len(values) > 1:
                try:
                    selected_ids.append(int(values[1]))
                except (ValueError, TypeError):
                    continue

        if not selected_ids:
            messagebox.showwarning(
                "Duyệt phiếu",
                "Hãy tích ô Chọn ở ít nhất một phiếu cần duyệt."
            )
            return

        c = self.db.conn.cursor()
        records = []

        for bid in selected_ids:
            c.execute("""
                SELECT book_id, due_date, request_date
                FROM borrowings
                WHERE id = ?
                  AND status = 'PendingReturn'
            """, (bid,))
            result = c.fetchone()

            if result:
                records.append((bid, result[0], result[1], result[2]))

        if not records:
            messagebox.showwarning(
                "Duyệt phiếu",
                "Các phiếu đã chọn không còn ở trạng thái chờ xác nhận."
            )
            return

        if not messagebox.askyesno(
            "Xác nhận",
            "Duyệt {} phiếu đã chọn?".format(len(records))
        ):
            return

        try:
            approved = 0

            for bid, book_id, due, req in records:
                ref_date = datetime.now().date()

                if req:
                    try:
                        ref_date = datetime.strptime(
                            req, "%Y-%m-%d"
                        ).date()
                    except (ValueError, TypeError):
                        pass

                late = 0

                if due:
                    try:
                        due_date = datetime.strptime(
                            due, "%Y-%m-%d"
                        ).date()
                        late = max((ref_date - due_date).days, 0)
                    except (ValueError, TypeError):
                        pass

                fine = late * FINE_PER_DAY

                c.execute("""
                    UPDATE borrowings
                    SET status = 'Returned',
                        return_date = ?,
                        fine = ?
                    WHERE id = ?
                      AND status = 'PendingReturn'
                """, (ref_date.isoformat(), fine, bid))

                if c.rowcount > 0:
                    c.execute("""
                        UPDATE books
                        SET available = available + 1
                        WHERE id = ?
                    """, (book_id,))
                    approved += 1

            self.db.conn.commit()

        except Exception as e:
            self.db.conn.rollback()
            messagebox.showerror(
                "Lỗi",
                "Không thể duyệt phiếu:\n{}".format(e)
            )
            return

        self.checked_rows["pending"].clear()
        self.pending_checked.clear()
        self.load_pending()
        self.load_returns()
        self.load_overdue_tab()

        self.show_return_success(
            "Duyệt trả sách thành công!",
            "Đã xác nhận trả thành công {} phiếu.".format(
                approved
            )
        )

    def __init__(self, root):
        self.root = root
        self.root.title("Hệ Thống Quản Lý Thư Viện")
        self.root.geometry("1300x760")
        self.root.minsize(1050,650)
        self.db = Database()
        self.user = None
        self.role = None
        self.C = {
            "bg":"#F5F7FA","side":"#FFFFFF","side2":"#EAF7EF",
            "green":"#2E8B57","green2":"#49B66B","dark":"#24313A","muted":"#718096",
            "border":"#D9E2E8","blue":"#3578E5","red":"#D9534F",
            "orange":"#E9A23B"}
        self.style()
        self.root.protocol("WM_DELETE_WINDOW", self.exit)
        self.login()

    def style(self):
        s=ttk.Style()
        try: s.theme_use("clam")
        except: pass
        s.configure("Treeview",rowheight=34,font=("Segoe UI",10),
                    background="white",fieldbackground="white")
        s.configure("Treeview.Heading",font=("Segoe UI",10,"bold"),
                    background="#EAF2EF",foreground=self.C["dark"],padding=8)
        # Bang nam trong khung bo goc: bo vien mac dinh cua Treeview
        s.layout("Round.Treeview",[("Treeview.treearea",{"sticky":"nswe"})])
        s.configure("Round.Treeview",rowheight=36,font=("Segoe UI",10),background="white",
                    fieldbackground="white",borderwidth=0,relief="flat")
        s.configure("Round.Treeview.Heading",font=("Segoe UI",10,"bold"),background="#EAF2EF",
                    foreground=self.C["dark"],padding=8,relief="flat",borderwidth=0)
        s.map("Round.Treeview",background=[("selected","#CFEAD9")],foreground=[("selected",self.C["dark"])])
        s.map("Treeview", background=[("selected", "#CFEAD9")], foreground=[("selected", self.C["dark"])])

    def clear(self, parent=None):
        parent = parent or self.root
        for w in parent.winfo_children(): w.destroy()

    def button(self,p,text,cmd,kind="green",width=15):
        colors={"green":(self.C["green"],"#246B45","white"),
                "blue":(self.C["blue"],"#285FB7","white"),
                "red":(self.C["red"],"#B63D39","white"),
                "gray":("#E8EDF0","#D8E0E5",self.C["dark"]),
                "orange":(self.C["orange"],"#C98A28","white")}
        bg,active,fg=colors[kind]
        return tk.Button(p,text=text,command=cmd,width=width,bg=bg,
                         activebackground=active,fg=fg,activeforeground=fg,
                         relief="flat",bd=0,font=("Segoe UI",10,"bold"),
                         cursor="hand2",pady=7)

    def rbutton(self,p,text,cmd,kind="green",width=130,height=40,bg="white"):
        """Nut bo goc cung bang mau voi self.button(); bg = mau nen cua widget cha (de goc bo hoa vao nen)."""
        C=self.C
        cols={"green":(C["green"],"#246B45","white"),"blue":(C["blue"],"#285FB7","white"),
              "red":(C["red"],"#B63D39","white"),"gray":("#E8EDF0","#D8E0E5",C["dark"]),
              "orange":(C["orange"],"#C98A28","white")}
        n,h,fg=cols[kind]
        return RoundButton(p,text,cmd,width,height,12,n,h,fg,bg)

