    def login_glass(self):
        C=self.C; dark="#1E3A5F"; blue="#1F5FB4"
        W,H=1300,760                # kich thuoc anh nen
        X0,Y0,CW,P,FW,FH,BH=800,255,440,40,360,46,48   # vi tri the + kich thuoc cac thanh phan trong anh
        DX=46                       # o nhap lui vao de chua bieu tuong (nguoi dung / o khoa)
        PAD=26                      # le bong do quanh the kinh trong anh
        self.root.state("normal"); self.root.update_idletasks()
        sw,sh=self.root.winfo_screenwidth(),self.root.winfo_screenheight()
        if sw<W or sh<H: raise RuntimeError("man hinh nho")
        self.root.geometry("{}x{}+{}+{}".format(W,H,(sw-W)//2,max(0,(sh-H)//2-20)))
        self.root.resizable(False,False)
        cv=tk.Canvas(self.root,width=W,height=H,highlightthickness=0,bd=0,bg=C["bg"]); cv.pack(fill="both",expand=True)
        dec=lambda t:tk.PhotoImage(data="".join(t.split()))
        bg,card,nb,hb=dec(LOGIN_BG_B64),dec(LOGIN_CARD_B64),dec(LOGIN_BTN_B64),dec(LOGIN_BTN_HOVER_B64)
        self._login_imgs=[bg,card,nb,hb]   # giu tham chieu de anh khong bi xoa
        kw=dict(font=("Segoe UI",11),bd=0,relief="flat",bg="white",fg=dark,
                highlightthickness=0,insertbackground=dark)
        self.eu=tk.Entry(cv,**kw)
        self.ep=tk.Entry(cv,show="*",**kw)
        self.show_pw=False
        cv.create_image(0,0,image=bg,anchor="nw")
        cv.create_image(X0-PAD,Y0-PAD,image=card,anchor="nw")
        # ---- tieu de tuong tac: bam de xem thanh vien nhom ----
        TF=("Segoe UI",17,"bold")
        cv.create_text(X0+CW//2,192,text="QUẢN LÝ THƯ VIỆN",fill=blue,font=TF,tags="ttl")
        cv.create_text(X0+CW//2,244,text="▾",fill="#6C93C9",font=("Segoe UI",9),tags="ttl")
        # ---- khung dang nhap (giu nguyen cac de muc) ----
        cv.create_text(X0+P,Y0+34,text="Đăng nhập",anchor="nw",fill=dark,font=("Segoe UI",26,"bold"))
        cv.create_text(X0+P+4,Y0+112,text="Tên đăng nhập",anchor="nw",fill=dark,font=("Segoe UI",10,"bold"))
        cv.create_text(X0+P+4,Y0+200,text="Mật khẩu",anchor="nw",fill=dark,font=("Segoe UI",10,"bold"))
        cv.create_window(X0+P+DX,Y0+136+9,anchor="nw",width=FW-DX-16,height=28,window=self.eu)
        cv.create_window(X0+P+DX,Y0+224+9,anchor="nw",width=FW-DX-16-34,height=28,window=self.ep)
        cv.create_text(X0+P+FW-26,Y0+224+FH//2,text="👁",fill="#718096",
                       font=("Segoe UI Emoji",13),tags="eye")
        bx,by=X0+P,Y0+296
        bimg=cv.create_image(bx,by,image=nb,anchor="nw",tags="btn")
        cv.create_text(bx+FW//2,by+BH//2,text="ĐĂNG NHẬP",fill="white",font=("Segoe UI",11,"bold"),tags="btn")
        cv.create_text(X0+CW//2,Y0+374,text="Demo: admin / 123456",anchor="n",fill="#4A5568",font=("Segoe UI",9))
        cv.create_text(X0+CW//2,Y0+394,text="Chưa có tài khoản? Đăng ký ngay",anchor="n",fill=blue,
                       font=("Segoe UI",10,"bold","underline"),tags="reg")
        cv.tag_bind("reg","<Button-1>",lambda e:self.register())
        cv.tag_bind("reg","<Enter>",lambda e:cv.config(cursor="hand2"))
        cv.tag_bind("reg","<Leave>",lambda e:cv.config(cursor=""))
        def toggle(e=None):
            self.show_pw=not self.show_pw
            self.ep.config(show="" if self.show_pw else "*")
            cv.itemconfig("eye",text="🙈" if self.show_pw else "👁")
        cv.tag_bind("eye","<Button-1>",toggle)
        cv.tag_bind("eye","<Enter>",lambda e:cv.config(cursor="hand2"))
        cv.tag_bind("eye","<Leave>",lambda e:cv.config(cursor=""))
        cv.tag_bind("btn","<Button-1>",lambda e:self.do_login())
        cv.tag_bind("btn","<Enter>",lambda e:(cv.itemconfig(bimg,image=hb),cv.config(cursor="hand2")))
        cv.tag_bind("btn","<Leave>",lambda e:(cv.itemconfig(bimg,image=nb),cv.config(cursor="")))

        # ---- bang thanh vien nhom (the kinh o ben trai) ----
        PX,PY,PW=92,120,440          # vi tri / do rong bang tren anh nen
        HEAD,ROW,FOOT,CAP=104,40,30,PAD+36
        members=[]
        for m in list(TEAM_MEMBERS)[:8]:
            members.append((str(m),"") if isinstance(m,str) else (str(m[0]),str(m[1]) if len(m)>1 else ""))
        if not members: members=[("(Chưa có thành viên - hãy điền vào TEAM_MEMBERS)","")]
        n=len(members)
        full=dec(TEAM_PANEL_B64)                       # bang cao toi da 8 dong
        ih=2*PAD+HEAD+n*ROW+FOOT; iw=full.width()
        pimg=tk.PhotoImage(width=iw,height=ih)         # cat phan tren + ghep phan duoi (goc bo) theo so thanh vien
        pimg.tk.call(pimg.name,"copy",full.name,"-from",0,0,iw,ih-CAP,"-to",0,0)
        pimg.tk.call(pimg.name,"copy",full.name,"-from",0,full.height()-CAP,iw,full.height(),"-to",0,ih-CAP)
        self._login_imgs+= [full,pimg]
        state={"open":False,"job":None}
        def close_team(e=None):
            if state["job"]:
                try: self.root.after_cancel(state["job"])
                except Exception: pass
                state["job"]=None
            try: cv.delete("team")
            except tk.TclError: return
            state["open"]=False
        def open_team():
            state["open"]=True
            cv.create_image(PX-PAD,PY-PAD,image=pimg,anchor="nw",tags="team")
            cv.create_text(PX+32,PY+30,text="Thành viên nhóm",anchor="w",fill=dark,font=("Segoe UI",16,"bold"),tags="team")
            if TEAM_NAME:
                cv.create_text(PX+32,PY+62,text=TEAM_NAME,anchor="w",fill="#4A6A94",font=("Segoe UI",10),tags="team")
            cv.create_text(PX+PW-30,PY+32,text="✕",fill="#6C7F99",font=("Segoe UI",12,"bold"),tags=("team","tx"))
            cv.create_line(PX+32,PY+HEAD-12,PX+PW-32,PY+HEAD-12,fill="#C9D8EE",tags="team")
            for i,(nm,rl) in enumerate(members):
                cy=PY+HEAD+i*ROW+ROW//2
                cv.create_oval(PX+32,cy-13,PX+58,cy+13,fill=blue,outline="",tags="team")
                cv.create_text(PX+45,cy,text=str(i+1),fill="white",font=("Segoe UI",10,"bold"),tags="team")
                cv.create_text(PX+72,cy,text=nm,anchor="w",fill=dark,font=("Segoe UI",11,"bold"),tags="team")
                if rl: cv.create_text(PX+PW-32,cy,text=rl,anchor="e",fill="#5A7396",font=("Segoe UI",9),tags="team")
            cv.tag_bind("tx","<Button-1>",close_team)
            cv.tag_bind("tx","<Enter>",lambda e:cv.config(cursor="hand2"))
            cv.tag_bind("tx","<Leave>",lambda e:cv.config(cursor=""))
            cv.move("team",0,16)                        # hieu ung truot len
            def slide(k=0):
                if k>=5 or not state["open"]: state["job"]=None; return
                cv.move("team",0,-3 if k<4 else -4)
                state["job"]=self.root.after(16,lambda:slide(k+1))
            slide()
        def toggle_team(e=None):
            if state["open"]: close_team()
            else: open_team()
        cv.tag_bind("ttl","<Button-1>",toggle_team)
        cv.tag_bind("ttl","<Enter>",lambda e:(cv.itemconfig("ttl",fill="#3B82D6"),cv.config(cursor="hand2")))
        cv.tag_bind("ttl","<Leave>",lambda e:(cv.itemconfig("ttl",fill=blue),cv.config(cursor="")))
        def on_escape(e=None):
            try:
                if cv.winfo_exists() and state["open"]: close_team()
            except tk.TclError: pass
        self.root.bind("<Escape>",on_escape)
        self.eu.focus()
        self.eu.bind("<Return>",lambda e:(self.ep.focus(),"break")[1])
        self.ep.bind("<Return>",lambda e:(self.do_login(),"break")[1])
        self.root.bind("<Return>",lambda e:self.do_login())

    ROLES=("Admin","Librarian","User")

    def do_login(self):
        uname=self.eu.get().strip(); pw=self.ep.get()
        if not uname or not pw:
            messagebox.showwarning("Đăng nhập","Vui lòng nhập tên đăng nhập và mật khẩu."); return
        c=self.db.conn.cursor()
        c.execute("SELECT username,password,role,status FROM users WHERE username=? COLLATE NOCASE",(uname,))
        r=c.fetchone()
        if not r:
            messagebox.showerror("Đăng nhập","Sai tài khoản hoặc mật khẩu."); return
        stored=r[1] or ""
        # Mat khau dung dinh dang SHA-256 (64 ky tu hex) thi so sanh hash; nguoc lai la plaintext cu
        is_hash=len(stored)==64 and all(ch in "0123456789abcdef" for ch in stored.lower())
        ok=(stored==hash_pw(pw)) if is_hash else (stored==pw)
        if not ok:
            messagebox.showerror("Đăng nhập","Sai tài khoản hoặc mật khẩu."); return
        if r[3]!="Active":
            messagebox.showerror("Đăng nhập","Tài khoản đang bị khóa. Vui lòng liên hệ Admin."); return
        if not is_hash:
            # Nang cap mat khau plaintext cu len hash
            c.execute("UPDATE users SET password=? WHERE username=?",(hash_pw(pw),r[0]))
            self.db.conn.commit()
        self.user,self.role=r[0],r[2]
        self.root.unbind("<Return>"); self.root.unbind("<Escape>")
        self.root.resizable(True,True)
        self.main()

    # ---------------- REGISTER ----------------
    PW_RULE="Mật khẩu phải có ít nhất 6 ký tự, gồm chữ in hoa, chữ thường, chữ số và ký tự đặc biệt (ví dụ: ! @ # $ %)."

    @staticmethod
    def check_password(pw):
        pw=pw or ""
        miss=[]
        if len(pw)<6: miss.append("tối thiểu 6 ký tự ")
        if not re.search(r"[A-Z]",pw): miss.append("chữ in hoa(A-Z)")
        if not re.search(r"[a-z]",pw): miss.append("chữ thường(a-z)")
        if not re.search(r"[0-9]",pw): miss.append("chữ số(0-9)")
        if not re.search(r"[^A-Za-z0-9\s]",pw): miss.append("và ký tự đặc biệt")
        if re.search(r"\s",pw): miss.append("không chứa khoảng trắng")
        if miss:
            return "Mật khẩu cần phải có " + ", ".join(miss) + "."
        return None

    def check_account(self,uname,pw,pw2=None):
        """Kiem tra du lieu tai khoan moi. Tra ve chuoi loi, hoac None neu hop le."""
        if not re.fullmatch(r"[A-Za-z0-9_.]{3,30}",uname or ""):
            return "Tên đăng nhập gồm 3-30 ký tự: chữ không dấu, số, dấu _ hoặc dấu chấm."
        err=self.check_password(pw)
        if err: return err
        if pw2 is not None and pw!=pw2:
            return "Mật khẩu nhập lại không khớp."
        c=self.db.conn.cursor()
        c.execute("SELECT 1 FROM users WHERE lower(username)=lower(?)",(uname,))
        if c.fetchone():
            return "Tên đăng nhập đã tồn tại."
        return None

    def create_account(self,uname,pw,role="User",full_name=""):
        c=self.db.conn.cursor()
        c.execute("""INSERT INTO users(username,password,role,status,full_name,created_at)
                     VALUES(?,?,?,?,?,?)""",
                  (uname,hash_pw(pw),role,"Active",full_name,datetime.now().strftime("%Y-%m-%d %H:%M")))
        self.db.conn.commit()

    def register(self):
        try: self.register_glass()
        except Exception:
            self.login(); self.register_dialog()

    def register_glass(self):
        C=self.C; dark="#1E3A5F"; blue="#1F5FB4"
        W,H=1300,760
        # khung dang ky trong anh nen REGISTER_BG_B64: x 440..860, y 54..698 (rong 420, cao 644)
        FX0,FX1,FY0,FY1=440,860,54,698
        FW,BH=360,48                            # o nhap 360x46, nut 360x48 (cung kich thuoc login_glass)
        X0=FX0+(FX1-FX0-FW)//2                  # le trai cua noi dung: can giua trong khung
        CX=(FX0+FX1)//2
        DX=46                                   # o nhap lui vao chua bieu tuong
        self.root.state("normal"); self.root.update_idletasks()
        sw,sh=self.root.winfo_screenwidth(),self.root.winfo_screenheight()
        if sw<W or sh<H: raise RuntimeError("man hinh nho")
        self.clear(); self.root.unbind("<Return>")
        self.root.geometry("{}x{}+{}+{}".format(W,H,(sw-W)//2,max(0,(sh-H)//2-20)))
        self.root.resizable(False,False)
        cv=tk.Canvas(self.root,width=W,height=H,highlightthickness=0,bd=0,bg=C["bg"]); cv.pack(fill="both",expand=True)
        dec=lambda t:tk.PhotoImage(data="".join(t.split()))
        bg,fu,fl,nb,hb=dec(REGISTER_BG_B64),dec(REGISTER_FIELD_USER_B64),dec(REGISTER_FIELD_LOCK_B64),dec(LOGIN_BTN_B64),dec(LOGIN_BTN_HOVER_B64)
        self._reg_imgs=[bg,fu,fl,nb,hb]         # giu tham chieu de anh khong bi xoa
        kw=dict(font=("Segoe UI",11),bd=0,relief="flat",bg="white",fg=dark,
                highlightthickness=0,insertbackground=dark)
        ents=[tk.Entry(cv,**kw) for _ in range(4)]
        ents[2].config(show="*"); ents[3].config(show="*")
        cv.create_image(0,0,image=bg,anchor="nw")
        cv.create_text(CX,FY0+40,text="Đăng ký",anchor="n",fill=dark,font=("Segoe UI",26,"bold"))
        cv.create_text(CX,FY0+92,text="Tài khoản mới có vai trò Người dùng",
                       anchor="n",fill="#4A5568",font=("Segoe UI",9))
        labels=("Họ và tên","Tên đăng nhập *","Mật khẩu *","Nhập lại mật khẩu *")
        for n,(lab,e) in enumerate(zip(labels,ents)):
            ly=FY0+132+92*n; fy=ly+26
            cv.create_text(X0+4,ly,text=lab,anchor="nw",fill=dark,font=("Segoe UI",10,"bold"))
            cv.create_image(X0-8,fy-8,image=fu if n<2 else fl,anchor="nw")
            cv.create_window(X0+DX,fy+9,anchor="nw",width=FW-DX-16-(34 if n>=2 else 0),height=28,window=e)
            if n>=2:
                cv.create_text(X0+FW-26,fy+23,text="👁",fill="#718096",
                               font=("Segoe UI Emoji",13),tags="eye")
        shown=[False]
        def toggle(ev=None):
            shown[0]=not shown[0]
            for e in ents[2:]: e.config(show="" if shown[0] else "*")
            cv.itemconfig("eye",text="🙈" if shown[0] else "👁")
        cv.tag_bind("eye","<Button-1>",toggle)
        cv.tag_bind("eye","<Enter>",lambda e:cv.config(cursor="hand2"))
        cv.tag_bind("eye","<Leave>",lambda e:cv.config(cursor=""))
        bx,by=X0,FY0+132+92*4+2
        bimg=cv.create_image(bx,by,image=nb,anchor="nw",tags="btn")
        cv.create_text(bx+FW//2,by+BH//2,text="ĐĂNG KÝ",fill="white",font=("Segoe UI",11,"bold"),tags="btn")
        cv.create_text(CX,by+BH+22,text="Đã có tài khoản? Đăng nhập",anchor="n",fill=blue,
                       font=("Segoe UI",10,"bold","underline"),tags="back")
        def submit(ev=None):
            self.do_register(None,ents[0].get().strip(),ents[1].get().strip(),ents[2].get(),ents[3].get())
            return "break"
        cv.tag_bind("btn","<Button-1>",lambda e:submit())
        cv.tag_bind("btn","<Enter>",lambda e:(cv.itemconfig(bimg,image=hb),cv.config(cursor="hand2")))
        cv.tag_bind("btn","<Leave>",lambda e:(cv.itemconfig(bimg,image=nb),cv.config(cursor="")))
        cv.tag_bind("back","<Button-1>",lambda e:self.login())
        cv.tag_bind("back","<Enter>",lambda e:cv.config(cursor="hand2"))
        cv.tag_bind("back","<Leave>",lambda e:cv.config(cursor=""))
        for n,e in enumerate(ents):
            e.bind("<Return>",(lambda ev,nx=ents[n+1]:(nx.focus(),"break")[1]) if n<3 else submit)
            e.bind("<Escape>",lambda ev:self.login())
        self.root.bind("<Return>",submit)
        ents[0].focus()

    def register_dialog(self):
        C=self.C
        win=tk.Toplevel(self.root); win.title("Đăng ký tài khoản"); win.configure(bg="white")
        win.resizable(False,False); win.transient(self.root)
        w,h=440,610
        self.root.update_idletasks()
        x=self.root.winfo_rootx()+max(0,(self.root.winfo_width()-w)//2)
        y=self.root.winfo_rooty()+max(0,(self.root.winfo_height()-h)//2)
        win.geometry("{}x{}+{}+{}".format(w,h,x,y))
        try: win.wait_visibility(); win.grab_set()
        except tk.TclError: pass
        tk.Label(win,text="Đăng ký tài khoản",bg="white",fg=C["dark"],
                 font=("Segoe UI",20,"bold")).pack(anchor="w",padx=40,pady=(30,2))
        tk.Label(win,text="Tài khoản mới có vai trò Người dùng (tra cứu sách).",bg="white",
                 fg=C["muted"],font=("Segoe UI",9)).pack(anchor="w",padx=40,pady=(0,14))
        ents={}
        for key,label,hide in (("name","Họ và tên",False),
                               ("user","Tên đăng nhập *",False),
                               ("pw","Mật khẩu *",True),
                               ("pw2","Nhập lại mật khẩu *",True)):
            tk.Label(win,text=label,bg="white",fg=C["dark"],font=("Segoe UI",10,"bold")).pack(anchor="w",padx=40)
            e=tk.Entry(win,font=("Segoe UI",11),relief="solid",bd=1,show="*" if hide else "")
            e.pack(fill="x",padx=40,ipady=7,pady=(4,12)); ents[key]=e
        shown=tk.BooleanVar(value=False)
        def toggle():
            for k in ("pw","pw2"): ents[k].config(show="" if shown.get() else "*")
        tk.Checkbutton(win,text="Hiện mật khẩu",variable=shown,command=toggle,bg="white",
                       activebackground="white",font=("Segoe UI",9)).pack(anchor="w",padx=36)
        def submit():
            self.do_register(win,ents["name"].get().strip(),ents["user"].get().strip(),
                             ents["pw"].get(),ents["pw2"].get())
        self.button(win,"ĐĂNG KÝ",submit,width=30).pack(fill="x",padx=40,pady=(18,6))
        self.button(win,"Quay lại đăng nhập",win.destroy,"gray",30).pack(fill="x",padx=40)
        ents["name"].focus()
        win.bind("<Return>",lambda e:submit())
        win.bind("<Escape>",lambda e:win.destroy())

    def do_register(self,win,full_name,uname,pw,pw2):
        parent=win or self.root
        err=self.check_account(uname,pw,pw2)
        if err:
            messagebox.showerror("Đăng ký",err,parent=parent); return False
        try: self.create_account(uname,pw,"User",full_name)
        except sqlite3.IntegrityError:
            messagebox.showerror("Đăng ký","Tên đăng nhập đã tồn tại.",parent=parent); return False
        messagebox.showinfo("Đăng ký","Đăng ký thành công! Hãy đăng nhập bằng tài khoản mới.",parent=parent)
        if win is not None: win.destroy()
        else: self.login()                  # quay ve man hinh dang nhap
        try:   # dien san ten dang nhap vao man hinh dang nhap
            self.eu.delete(0,"end"); self.eu.insert(0,uname)
            self.ep.delete(0,"end"); self.ep.focus()
        except tk.TclError: pass
        return True

