    def _book_sort_changed(self, event=None):
        choice = self.book_sort_combo.get()
        mapping = {
            "Tên sách (A → Z)": ("title", False),
            "Tên sách (Z → A)": ("title", True),
            "Mã sách": ("code", False),
            "Năm mới nhất": ("year", True),
            "Số lượng thấp nhất": ("available", False),
        }
        self._book_sort_key, self._book_sort_desc = mapping.get(choice, ("title", False))
        self.load_books()

    def _refresh_books_page(self):
        self.refresh_book_categories()
        self.load_books()

    def export_books_excel(self):
        """Xuất danh sách sách ra Excel (.xlsx); yêu cầu openpyxl."""
        path = filedialog.asksaveasfilename(title="Xuất danh sách sách", defaultextension=".xlsx",
                    filetypes=[("Excel Workbook", "*.xlsx")], initialfile="danh_sach_sach.xlsx")
        if not path:
            return
        try:
            from openpyxl import Workbook
            from openpyxl.styles import Font, PatternFill, Alignment
            wb = Workbook(); ws = wb.active; ws.title = "Danh sách sách"
            headers = ["Mã sách", "Tên sách", "Tác giả", "Thể loại", "Nhà xuất bản", "Năm xuất bản", "Tổng số", "Còn khả dụng", "Tình trạng"]
            ws.append(headers)
            for cell in ws[1]:
                cell.font = Font(bold=True, color="FFFFFF")
                cell.fill = PatternFill("solid", fgColor="168253")
                cell.alignment = Alignment(horizontal="center")
            cur = self.db.conn.cursor()
            cur.execute("SELECT code,title,author,category,publisher,year,COALESCE(quantity,0),COALESCE(available,0) FROM books ORDER BY title COLLATE NOCASE")
            for row in cur.fetchall():
                a = row[7] or 0
                status = "Hết sách" if a <= 0 else ("Sắp hết" if a <= 2 else "Còn sách")
                ws.append(list(row) + [status])
            for col, width in enumerate([14, 30, 25, 18, 24, 15, 12, 16, 16], 1):
                ws.column_dimensions[chr(64+col)].width = width
            ws.freeze_panes = "A2"; ws.auto_filter.ref = ws.dimensions
            wb.save(path)
            messagebox.showinfo("Xuất Excel", "Đã xuất danh sách sách thành công.\n" + path)
        except ImportError:
            messagebox.showerror("Thiếu thư viện", "Cần cài openpyxl để xuất Excel.\nMở Terminal và chạy: pip install openpyxl")
        except Exception as exc:
            messagebox.showerror("Lỗi xuất Excel", "Không thể xuất tệp.\n{}".format(exc))

    def _update_book_dashboard(self):
        """Cap nhat cac the thong ke, bieu do tron va bieu do ton kho."""
        if not hasattr(self, "book_category_summary"):
            return
        c = self.db.conn.cursor()

        c.execute("SELECT COALESCE(NULLIF(TRIM(category),''),'Khác'), COUNT(*), COALESCE(SUM(quantity),0) "
                  "FROM books GROUP BY COALESCE(NULLIF(TRIM(category),''),'Khác') ORDER BY COUNT(*) DESC")
        cats = c.fetchall()
        total_titles = sum(int(r[1] or 0) for r in cats)
        if hasattr(self, "book_category_chart"):
            cv = self.book_category_chart
            cv.delete("all")
            palette = ["#238A5B", "#3B82F6", "#8B5CF6", "#F59E0B", "#EC4899", "#64748B"]
            # Draw a donut using filled pie slices, then mask the center. This is more
            # reliable than Canvas arc outlines with negative extents across Windows/Tk versions.
            cw = max(cv.winfo_width(), 112); ch = max(cv.winfo_height(), 112)
            cx, cy = cw // 2, ch // 2
            radius = min(42, cw // 2 - 5, ch // 2 - 5)
            inner = max(20, radius - 13)
            if total_titles:
                angle = 90.0
                for i, (name, count, qty) in enumerate(cats):
                    extent = 360.0 * int(count or 0) / total_titles
                    # Tk Canvas may fail to paint a pieslice whose extent is exactly
                    # 360 degrees (common when every book belongs to one category).
                    # Draw a full oval for that case; use pie slices for multiple categories.
                    if extent >= 359.999:
                        cv.create_oval(cx-radius, cy-radius, cx+radius, cy+radius,
                                       fill=palette[i % len(palette)], outline="white", width=1)
                    else:
                        cv.create_arc(cx-radius, cy-radius, cx+radius, cy+radius,
                                      start=angle, extent=extent, style="pieslice",
                                      fill=palette[i % len(palette)], outline="white", width=1)
                    angle += extent
                cv.create_oval(cx-inner, cy-inner, cx+inner, cy+inner, fill="white", outline="white")
                cv.create_text(cx, cy-4, text=str(total_titles), fill=self.C["dark"],
                               font=("Segoe UI", 14, "bold"))
                cv.create_text(cx, cy+13, text="đầu sách", fill=self.C["muted"],
                               font=("Segoe UI", 7))
            else:
                cv.create_oval(cx-radius, cy-radius, cx+radius, cy+radius,
                               outline="#E5E7EB", width=8)
                cv.create_text(cx, cy, text="0", fill=self.C["muted"], font=("Segoe UI", 13, "bold"))
        cat_lines = []
        for i, (name, count, qty) in enumerate(cats[:5]):
            pct = (100.0 * int(count or 0) / total_titles) if total_titles else 0
            cat_lines.append("{}  {}  ({}%)".format(name, count, round(pct)))
        if len(cats) > 5:
            cat_lines.append("+ {} thể loại khác".format(len(cats)-5))
        self.book_category_summary.config(text="\n".join(cat_lines) or "Chưa có dữ liệu")

        c.execute("SELECT title, COALESCE(available,0) FROM books "
                  "WHERE COALESCE(available,0)<=2 ORDER BY available ASC, title LIMIT 5")
        low = c.fetchall()
        for child in self.book_low_summary.winfo_children():
            child.destroy()
        if low:
            for i, (title, qty) in enumerate(low):
                row = tk.Frame(self.book_low_summary, bg="white")
                row.pack(fill="x", pady=2)
                tk.Label(row, text=str(i+1), bg="#FFF0ED", fg="#C64235",
                         font=("Segoe UI", 8, "bold"), width=3, pady=3).pack(side="left", padx=(0, 7))
                tk.Label(row, text=(title or "Chưa đặt tên")[:28], bg="white", fg=self.C["dark"],
                         font=("Segoe UI", 8), anchor="w").pack(side="left", fill="x", expand=True)
                tk.Label(row, text=str(qty), bg="#FFF0ED" if int(qty or 0) <= 0 else "#FFF7E5",
                         fg="#C64235" if int(qty or 0) <= 0 else "#946200",
                         font=("Segoe UI", 8, "bold"), width=4, pady=3).pack(side="right")
        else:
            tk.Label(self.book_low_summary, text="✓  Không có sách sắp hết",
                     bg="white", fg="#168253", font=("Segoe UI", 9)).pack(anchor="w", pady=8)

        c.execute("SELECT COUNT(*), COALESCE(SUM(quantity),0), COALESCE(SUM(available),0), "
                  "SUM(CASE WHEN COALESCE(available,0)<=2 AND COALESCE(available,0)>0 THEN 1 ELSE 0 END), "
                  "SUM(CASE WHEN COALESCE(available,0)<=0 THEN 1 ELSE 0 END) FROM books")
        row = c.fetchone() or (0, 0, 0, 0, 0)
        titles, total_copies, available_copies, low_count, out_count = [int(v or 0) for v in row]
        if hasattr(self, "quick_total"):
            self.quick_total.config(text="{}\nĐầu sách".format(titles))
            self.quick_available.config(text="{}\nBản có sẵn".format(available_copies))
            self.quick_low.config(text="{}\nSắp hết".format(low_count or 0))
        if hasattr(self, "dashboard_quick_total"):
            self.dashboard_quick_total.config(text="{}\nĐầu sách".format(titles))
            self.dashboard_quick_available.config(text="{}\nBản có sẵn".format(available_copies))
            self.dashboard_quick_low.config(text="{}\nSách sắp hết".format(low_count or 0))

        cv = self.book_stock_chart
        cv.delete("all")
        w = max(cv.winfo_width(), 260)
        h = max(cv.winfo_height(), 115)
        c.execute("SELECT code, COALESCE(quantity,0), COALESCE(available,0) FROM books ORDER BY code LIMIT 8")
        data = c.fetchall()
        if not data:
            cv.create_text(w//2, h//2, text="Chưa có dữ liệu", fill=self.C["muted"])
            return
        maxv = max([max(int(q or 0), int(a or 0)) for _, q, a in data] + [1])
        left, right, top, bottom = 30, 12, 20, h-25
        # Duong luoi va nhan truc Y giup doc so lieu de hon.
        for tick in range(0, 4):
            val = maxv * tick / 3
            y = bottom - (bottom-top) * tick / 3
            cv.create_line(left, y, w-right, y, fill="#E8EEF2", width=1)
            cv.create_text(left-7, y, text=str(round(val)), anchor="e",
                           fill="#7A8794", font=("Segoe UI", 7))
        group = (w-left-right) / max(len(data), 1)
        bw = max(5, min(12, group/3.2))
        for i, (code, q, a) in enumerate(data):
            q, a = int(q or 0), int(a or 0)
            x = left + i*group + group/2
            qh = (bottom-top)*q/maxv
            ah = (bottom-top)*a/maxv
            cv.create_rectangle(x-bw-1, bottom-qh, x-1, bottom, fill="#168253", outline="")
            cv.create_rectangle(x+1, bottom-ah, x+bw+1, bottom, fill="#B9C8D6", outline="")
            cv.create_text(x, bottom+11, text=(code or "")[-3:], fill="#657386", font=("Segoe UI", 7))
        cv.create_rectangle(w-102, 4, w-92, 12, fill="#168253", outline="")
        cv.create_text(w-87, 8, text="Tổng", anchor="w", fill=self.C["muted"], font=("Segoe UI", 7))
        cv.create_rectangle(w-52, 4, w-42, 12, fill="#B9C8D6", outline="")
        cv.create_text(w-37, 8, text="Còn", anchor="w", fill=self.C["muted"], font=("Segoe UI", 7))

    def sort_books_by(self, key):
        """Sắp xếp bảng sách khi nhấn tiêu đề cột."""
        if key == getattr(self, "_book_sort_key", "title"):
            self._book_sort_desc = not getattr(self, "_book_sort_desc", False)
        else:
            self._book_sort_key = key
            self._book_sort_desc = False
        self.load_books()

    def refresh_book_categories(self):
        """Nạp lại danh sách thể loại từ dữ liệu đang có."""
        if not hasattr(self, "book_category_filter"):
            return
        c = self.db.conn.cursor()
        c.execute("SELECT DISTINCT TRIM(category) FROM books WHERE category IS NOT NULL AND TRIM(category)<>'' ORDER BY category COLLATE NOCASE")
        categories = [r[0] for r in c.fetchall()]
        current = self.book_category_filter.get() or "Tất cả"
        values = ["Tất cả"] + categories
        self.book_category_filter.configure(values=values)
        self.book_category_filter.set(current if current in values else "Tất cả")

    def load_books(self, key=None):
        """Nạp danh sách sách, giữ lựa chọn khi có thể và lọc không dấu."""
        if not hasattr(self, "bt") or not self.bt.winfo_exists():
            return

        # Ghi nhớ sách đang chọn để thao tác tìm kiếm/lọc không làm mất chi tiết vô cớ.
        selected = self.bt.selection()
        selected_id = None
        if selected:
            values = self.bt.item(selected[0], "values")
            if values:
                selected_id = str(values[0])

        if key is None:
            key = self.bs.get().strip() if hasattr(self, "bs") else ""
        for item in self.bt.get_children():
            self.bt.delete(item)

        c = self.db.conn.cursor()
        sql = """SELECT id,code,title,author,category,publisher,year,
                        COALESCE(quantity,0),COALESCE(available,0),COALESCE(cover,'')
                 FROM books WHERE 1=1"""
        params = []
        if key:
            term = "%" + strip_accents(key).lower() + "%"
            sql += """ AND (
                lower(unaccent(COALESCE(code,''))) LIKE ? OR
                lower(unaccent(COALESCE(title,''))) LIKE ? OR
                lower(unaccent(COALESCE(author,''))) LIKE ? OR
                lower(unaccent(COALESCE(category,''))) LIKE ? OR
                lower(unaccent(COALESCE(publisher,''))) LIKE ?)"""
            params.extend([term] * 5)

        category = self.book_category_filter.get() if hasattr(self, "book_category_filter") else "Tất cả"
        if category and category != "Tất cả":
            sql += " AND TRIM(COALESCE(category,''))=?"
            params.append(category)
        stock = self.book_stock_filter.get() if hasattr(self, "book_stock_filter") else "Tất cả"
        if stock == "Còn sách":
            sql += " AND COALESCE(available,0)>2"
        elif stock == "Sắp hết":
            sql += " AND COALESCE(available,0)>0 AND COALESCE(available,0)<=2"
        elif stock == "Hết sách":
            sql += " AND COALESCE(available,0)<=0"

        sort_key = getattr(self, "_book_sort_key", "title")
        sort_desc = getattr(self, "_book_sort_desc", False)
        allowed_sort = {
            "id": "id", "code": "code", "title": "title", "author": "author",
            "category": "category", "publisher": "publisher", "year": "year",
            "quantity": "quantity", "available": "available"
        }
        sort_expr = allowed_sort.get(sort_key, "title")
        sql += " ORDER BY {} {} , id DESC".format(
            "COALESCE({},'')".format(sort_expr) if sort_key in ("code", "title", "author", "category", "publisher") else sort_expr,
            "DESC" if sort_desc else "ASC")
        c.execute(sql, params)
        rows = c.fetchall()

        if not hasattr(self, "_book_thumb_images"):
            self._book_thumb_images = {}
        for r in rows:
            available = r[8] or 0
            status = "Hết sách" if available <= 0 else ("Sắp hết" if available <= 2 else "Còn sách")
            tag = "out" if status == "Hết sách" else ("low" if status == "Sắp hết" else "")
            thumb = None
            if PIL_OK and r[9] and os.path.isfile(r[9]):
                try:
                    with Image.open(r[9]) as source:
                        source = ImageOps.exif_transpose(source).convert("RGB")
                        # Fit (contain), khong crop: giu tron bia va dung ti le goc.
                        source = ImageOps.contain(source, (38, 52), method=Image.Resampling.LANCZOS)
                        tile = Image.new("RGB", (40, 54), "white")
                        tile.paste(source, ((40-source.width)//2, (54-source.height)//2))
                    thumb = ImageTk.PhotoImage(tile)
                    self._book_thumb_images[str(r[0])] = thumb
                except Exception:
                    thumb = None
            values = tuple(r[:9]) + (status, "")
            self.bt.insert("", "end", iid=str(r[0]), values=values, image=thumb or "", tags=(tag,) if tag else ())

        c.execute("SELECT COUNT(*), COALESCE(SUM(quantity),0), COALESCE(SUM(available),0), SUM(CASE WHEN COALESCE(available,0)>0 AND COALESCE(available,0)<=2 THEN 1 ELSE 0 END), SUM(CASE WHEN COALESCE(available,0)<=0 THEN 1 ELSE 0 END) FROM books")
        titles, total, available_total, low_count, out_count = c.fetchone()
        low_count, out_count = low_count or 0, out_count or 0
        self.book_stats_label.config(
            text="{} kết quả  •  {} đầu sách  •  {} bản sách  •  {} bản có thể mượn  •  ⚠ {} đầu sách sắp hết  •  {} đầu sách hết".format(
                len(rows), titles, total, available_total, low_count, out_count),
            fg=self.C["red"] if out_count else ("#B7791F" if low_count else self.C["muted"]))

        # Chọn lại đúng sách nếu sách đó vẫn nằm trong kết quả lọc.
        if selected_id and self.bt.exists(selected_id):
            self.bt.selection_set(selected_id)
            self.bt.focus(selected_id)
            self.bt.see(selected_id)
            self.show_book_preview()
        elif rows:
            # Khi lọc hoặc tìm kiếm, tự chọn dòng đầu tiên để khung chi tiết luôn hữu ích.
            first = str(rows[0][0])
            self.bt.selection_set(first)
            self.bt.focus(first)
            self.show_book_preview()
        else:
            self.preview_title.config(text="Không tìm thấy sách")
            self.preview_author.config(text="")
            self.preview_meta.config(text="")
            self.preview_description.config(text="Thử đổi từ khóa hoặc bộ lọc.")
            self.preview_status.config(text="Không có dữ liệu", bg="#EDF2F7", fg="#718096")
            self.preview_code.config(text="—")
            self.preview_stock.config(text="— / —")
            self.cover_label.config(image="", text="CHƯA CÓ\nẢNH BÌA", bg="#F0F3F5")
            self.cover_label.image = None
        self._update_book_dashboard()

    def show_book_preview(self, event=None):
        selected = self.bt.selection()
        if not selected:
            return
        bid = self.bt.item(selected[0])["values"][0]
        row = self.db.conn.execute(
            "SELECT code,title,author,category,publisher,year,quantity,available,cover,description,edition FROM books WHERE id=?", (bid,)
        ).fetchone()
        if not row:
            return
        code,title,author,category,publisher,year,quantity,available,cover,description,edition = row
        quantity = int(quantity or 0)
        available = int(available or 0)
        if available <= 0:
            status, bg, fg = "Hết sách", "#FEE2E2", "#B91C1C"
        elif available <= 2:
            status, bg, fg = "Sắp hết", "#FFF1CC", "#9A6700"
        else:
            status, bg, fg = "Còn sách", "#DDF7E9", "#13804A"
        self.preview_status.config(text=status, bg=bg, fg=fg)
        self.preview_title.config(text=title or "Chưa có tên sách")
        self.preview_author.config(text="Tác giả: {}\nNhà xuất bản: {}\nNăm xuất bản: {}\nThể loại: {}".format(
            author or "Chưa cập nhật", publisher or "Chưa cập nhật", year or "—", category or "Chưa phân loại"))
        self.preview_meta.config(text="Ấn bản: {}".format(edition or "1"))
        self.preview_code.config(text=code or "—")
        self.preview_stock.config(text="{} / {}".format(available, quantity))
        self.preview_description.config(text=(description or "Chưa có mô tả.")[:420])
        self.cover_label.config(image="", text="CHƯA CÓ\nẢNH BÌA", bg="#F0F3F5")
        self.cover_label.image = None
        if cover and PIL_OK:
            cover_path = str(cover)
            if not os.path.isabs(cover_path):
                cover_path = os.path.join(BASE_DIR, cover_path)
            if os.path.isfile(cover_path):
                try:
                    with Image.open(cover_path) as source:
                        img = ImageOps.exif_transpose(source).convert("RGB")
                    # Contain preserves the entire front cover; no crop/stretch.
                    img = ImageOps.contain(img, (106, 154), method=Image.Resampling.LANCZOS)
                    canvas = Image.new("RGB", (112, 160), "#F0F3F5")
                    canvas.paste(img, ((112-img.width)//2, (160-img.height)//2))
                    self.cover_label.image = ImageTk.PhotoImage(canvas)
                    self.cover_label.config(image=self.cover_label.image, text="", bg="#F0F3F5")
                except Exception:
                    self.cover_label.config(image="", text="LỖI ĐỌC\nẢNH BÌA", bg="#FFF0F0")
                    self.cover_label.image = None

    def open_book_cover(self, event=None):
        """Mở ảnh bìa lớn khi nhấp đúp vào ảnh xem trước."""
        selected = self.bt.selection() if hasattr(self, "bt") else ()
        if not selected:
            return
        bid = self.bt.item(selected[0])["values"][0]
        row = self.db.conn.execute("SELECT title,cover FROM books WHERE id=?", (bid,)).fetchone()
        cover_path = str(row[1] or "") if row else ""
        if cover_path and not os.path.isabs(cover_path):
            cover_path = os.path.join(BASE_DIR, cover_path)
        if not row or not cover_path or not os.path.isfile(cover_path):
            messagebox.showinfo("Ảnh bìa", "Sách này chưa có tệp ảnh bìa hợp lệ.")
            return
        if not PIL_OK:
            messagebox.showinfo("Ảnh bìa", "Cần cài Pillow để xem ảnh bìa lớn: pip install pillow")
            return
        try:
            win = tk.Toplevel(self.root)
            win.title("Ảnh bìa — {}".format(row[0] or "Sách"))
            win.configure(bg="white")
            win.geometry("520x650")
            img = Image.open(cover_path)
            img = ImageOps.exif_transpose(img).convert("RGB")
            img = ImageOps.contain(img, (480, 570), method=Image.Resampling.LANCZOS)
            photo = ImageTk.PhotoImage(img)
            label = tk.Label(win, image=photo, bg="white")
            label.image = photo
            label.pack(expand=True, padx=15, pady=15)
            tk.Label(win, text=row[0] or "Sách", bg="white", fg=self.C["dark"],
                     font=("Segoe UI", 12, "bold"), wraplength=480).pack(pady=(0, 12))
        except Exception as exc:
            messagebox.showerror("Ảnh bìa", "Không thể mở ảnh bìa.\n{}".format(exc))

    def search_books(self):
        self.load_books()

    def add_book(self):
        self.book_dialog(None)

    def edit_book(self):
        selected = self.bt.selection()
        if not selected:
            messagebox.showwarning("Sửa sách", "Vui lòng chọn một cuốn sách.")
            return
        self.book_dialog(self.bt.item(selected[0])["values"][0])

    def book_dialog(self, bid):
        d = tk.Toplevel(self.root)
        d.title("Cập nhật sách" if bid else "Thêm sách mới")
        d.geometry("760x700")
        d.configure(bg=self.C["bg"])
        d.transient(self.root)
        d.grab_set()
        d.resizable(False, True)
        d.minsize(700, 620)
        c = self.db.conn.cursor()
        if bid:
            c.execute("SELECT code,title,author,category,publisher,year,quantity,cover,description,edition FROM books WHERE id=?", (bid,))
            data = c.fetchone()
            if not data:
                d.destroy()
                messagebox.showerror("Sách", "Không tìm thấy đầu sách cần cập nhật.")
                return
        else:
            data = ("", "", "", "", "", datetime.now().year, 1, "", "", "1")

        tk.Label(d, text="CẬP NHẬT SÁCH" if bid else "THÊM SÁCH MỚI", bg=self.C["bg"],
                 fg=self.C["dark"], font=("Segoe UI", 19, "bold")).pack(anchor="w", padx=25, pady=(18, 12))
        form = tk.Frame(d, bg="white", highlightbackground=self.C["border"], highlightthickness=1)
        form.pack(fill="both", expand=True, padx=25, pady=4)
        fields = [("Mã sách *", "code", data[0]), ("Tên sách *", "title", data[1]),
                  ("Tác giả", "author", data[2]), ("Thể loại", "category", data[3]),
                  ("Nhà xuất bản", "publisher", data[4]), ("Năm xuất bản", "year", data[5]),
                  ("Tổng số bản", "quantity", data[6]), ("Ấn bản", "edition", data[9])]
        entries = {}
        for i, (label, key, value) in enumerate(fields):
            box = tk.Frame(form, bg="white")
            box.grid(row=i//2, column=i%2, padx=14, pady=8, sticky="ew")
            tk.Label(box, text=label, bg="white", fg=self.C["dark"], font=("Segoe UI", 9, "bold")).pack(anchor="w")
            entry = tk.Entry(box, width=31, font=("Segoe UI", 10), relief="solid", bd=1)
            entry.pack(fill="x", ipady=5, pady=(4, 0))
            entry.insert(0, str(value if value is not None else ""))
            entries[key] = entry
        form.grid_columnconfigure(0, weight=1)
        form.grid_columnconfigure(1, weight=1)

        cover_var = tk.StringVar(value=data[7] or "")
        cover_row = tk.Frame(form, bg="white")
        cover_row.grid(row=4, column=0, columnspan=2, padx=14, pady=8, sticky="ew")
        tk.Label(cover_row, text="Đường dẫn ảnh bìa", bg="white", fg=self.C["dark"],
                 font=("Segoe UI", 9, "bold")).pack(anchor="w")
        cover_entry = tk.Entry(cover_row, textvariable=cover_var, font=("Segoe UI", 10), relief="solid", bd=1)
        cover_entry.pack(side="left", fill="x", expand=True, ipady=5, pady=(4, 0))
        self.button(cover_row, "Chọn ảnh", lambda: self.choose_cover(cover_var), "gray", 10).pack(side="left", padx=(8, 0), pady=(4, 0))

        desc_row = tk.Frame(form, bg="white")
        desc_row.grid(row=5, column=0, columnspan=2, padx=14, pady=8, sticky="ew")
        tk.Label(desc_row, text="Mô tả sách", bg="white", fg=self.C["dark"],
                 font=("Segoe UI", 9, "bold")).pack(anchor="w")
        description = tk.Text(desc_row, height=4, wrap="word", font=("Segoe UI", 10), relief="solid", bd=1)
        description.pack(fill="x", pady=(4, 0))
        description.insert("1.0", data[8] or "")

        tk.Label(form, text="* Trường bắt buộc. Số bản đang mượn sẽ được giữ nguyên khi cập nhật tổng số lượng.",
                 bg="white", fg=self.C["muted"], font=("Segoe UI", 8)).grid(row=6, column=0, columnspan=2, sticky="w", padx=14, pady=(2, 10))

        def save():
            values = {key: widget.get().strip() for key, widget in entries.items()}
            if not values["code"] or not values["title"]:
                messagebox.showwarning("Thiếu dữ liệu", "Mã sách và tên sách là bắt buộc.", parent=d)
                return
            try:
                year = int(values["year"])
                quantity = int(values["quantity"])
                if year < 0 or year > datetime.now().year + 5:
                    raise ValueError("year")
                if quantity < 0:
                    raise ValueError("quantity")
            except ValueError:
                messagebox.showerror("Dữ liệu không hợp lệ", "Năm xuất bản hoặc tổng số bản không hợp lệ.", parent=d)
                return
            try:
                c = self.db.conn.cursor()
                if bid:
                    c.execute("SELECT quantity,available FROM books WHERE id=?", (bid,))
                    old = c.fetchone()
                    if not old:
                        messagebox.showerror("Lỗi", "Đầu sách không còn tồn tại.", parent=d)
                        return
                    borrowed = max((old[0] or 0) - (old[1] or 0), 0)
                    if quantity < borrowed:
                        messagebox.showerror("Không thể cập nhật", "Tổng số bản ({}) không thể nhỏ hơn số đang mượn ({}).".format(quantity, borrowed), parent=d)
                        return
                    available = quantity - borrowed
                    c.execute("""UPDATE books SET code=?,title=?,author=?,category=?,publisher=?,year=?,
                                 quantity=?,available=?,cover=?,description=?,edition=? WHERE id=?""",
                              (values["code"], values["title"], values["author"], values["category"],
                               values["publisher"], year, quantity, available, cover_var.get().strip(),
                               description.get("1.0", "end-1c").strip(), values["edition"], bid))
                else:
                    c.execute("""INSERT INTO books(code,title,author,category,publisher,year,quantity,available,cover,description,edition)
                                 VALUES(?,?,?,?,?,?,?,?,?,?,?)""",
                              (values["code"], values["title"], values["author"], values["category"],
                               values["publisher"], year, quantity, quantity, cover_var.get().strip(),
                               description.get("1.0", "end-1c").strip(), values["edition"]))
                self.db.conn.commit()
                d.destroy()
                self.refresh_book_categories()
                self.load_books()
                messagebox.showinfo("Thành công", "Đã {} sách '{}'.".format("cập nhật" if bid else "thêm", values["title"]))
            except sqlite3.IntegrityError:
                messagebox.showerror("Trùng mã sách", "Mã sách đã tồn tại. Hãy nhập một mã khác.", parent=d)
            except sqlite3.Error as exc:
                self.db.conn.rollback()
                messagebox.showerror("Lỗi cơ sở dữ liệu", "Không thể lưu thông tin sách.\n{}".format(exc), parent=d)

        buttons = tk.Frame(d, bg=self.C["bg"])
        buttons.pack(fill="x", padx=25, pady=12)
        self.button(buttons, "HỦY", d.destroy, "gray", 13).pack(side="right", padx=(8, 0), ipady=5)
        self.button(buttons, "LƯU THÔNG TIN", save, "green", 17).pack(side="right", ipady=5)

    def choose_cover(self, var):
        path = filedialog.askopenfilename(filetypes=[("Ảnh bìa", "*.png *.jpg *.jpeg *.gif *.webp"), ("Tất cả tệp", "*.*")])
        if path:
            var.set(path)

    def delete_book(self):
        selected = self.bt.selection()
        if not selected:
            messagebox.showwarning("Xóa sách", "Vui lòng chọn một cuốn sách.")
            return
        bid = self.bt.item(selected[0])["values"][0]
        c = self.db.conn.cursor()
        c.execute("SELECT title FROM books WHERE id=?", (bid,))
        row = c.fetchone()
        if not row:
            self.load_books()
            return
        title = row[0]
        c.execute("SELECT COUNT(*) FROM borrowings WHERE book_id=? AND status IN ('Borrowing','PendingReturn')", (bid,))
        active = c.fetchone()[0]
        if active:
            messagebox.showerror("Không thể xóa", "Sách đang có {} phiếu mượn chưa hoàn tất. Hãy xử lý phiếu mượn trước.".format(active))
            return
        c.execute("SELECT COUNT(*) FROM borrowings WHERE book_id=?", (bid,))
        history = c.fetchone()[0]
        if history and not messagebox.askyesno("Xác nhận xóa", "Sách '{}' có {} phiếu mượn trong lịch sử. Xóa sách có thể ảnh hưởng đến việc tra cứu lịch sử. Bạn có chắc chắn muốn xóa?".format(title, history)):
            return
        if not history and not messagebox.askyesno("Xác nhận xóa", "Bạn có chắc chắn muốn xóa sách '{}'?".format(title)):
            return
        try:
            c.execute("DELETE FROM books WHERE id=?", (bid,))
            self.db.conn.commit()
            self.refresh_book_categories()
            self.load_books()
            messagebox.showinfo("Thành công", "Đã xóa sách '{}'.".format(title))
        except sqlite3.Error as exc:
            self.db.conn.rollback()
            messagebox.showerror("Lỗi cơ sở dữ liệu", "Không thể xóa sách.\n{}".format(exc))

